void dfs(vector<int>& a, vector<int>& cur, vector<bool>& used,
         vector<vector<int>>& res) {
    if (cur.size() == a.size()) { res.push_back(cur); return; }
    for (int i = 0; i < (int)a.size(); ++i) {
        if (used[i]) continue;
        used[i] = true; cur.push_back(a[i]);
        dfs(a, cur, used, res);
        used[i] = false; cur.pop_back();        // backtrack
    }
}

def permute(a):
    res, cur = [], []
    used = [False] * len(a)
    def dfs():
        if len(cur) == len(a):
            res.append(cur[:]); return
        for i, x in enumerate(a):
            if used[i]:
                continue
            used[i] = True; cur.append(x)
            dfs()
            used[i] = False; cur.pop()      # backtrack
    dfs()
    return res

class Solution {
    vector<vector<int>> res; vector<int> path; vector<bool> used;
    void dfs(vector<int>& a) {
        if (path.size() == a.size()) { res.push_back(path); return; }
        for (int i = 0; i < (int)a.size(); i++) {
            if (used[i]) continue;
            used[i] = true; path.push_back(a[i]);
            dfs(a);
            path.pop_back(); used[i] = false;
        }
    }
public:
    vector<vector<int>> permute(vector<int>& a) { used.assign(a.size(), false); dfs(a); return res; }
};

class Solution:
    def permute(self, a: list[int]) -> list[list[int]]:
        res, path = [], []
        used = [False] * len(a)
        def dfs():
            if len(path) == len(a):
                res.append(path[:]); return
            for i in range(len(a)):
                if used[i]:
                    continue
                used[i] = True; path.append(a[i])
                dfs()
                path.pop(); used[i] = False
        dfs()
        return res

class Solution {
    vector<vector<int>> res; vector<int> path; vector<bool> used;
    void dfs(vector<int>& a) {
        if (path.size() == a.size()) { res.push_back(path); return; }
        for (int i = 0; i < (int)a.size(); i++) {
            if (used[i]) continue;
            if (i && a[i] == a[i-1] && !used[i-1]) continue;
            used[i] = true; path.push_back(a[i]);
            dfs(a);
            path.pop_back(); used[i] = false;
        }
    }
public:
    vector<vector<int>> permuteUnique(vector<int>& a) {
        sort(a.begin(), a.end()); used.assign(a.size(), false); dfs(a); return res;
    }
};

class Solution:
    def permuteUnique(self, a: list[int]) -> list[list[int]]:
        a.sort()
        res, path = [], []
        used = [False] * len(a)
        def dfs():
            if len(path) == len(a):
                res.append(path[:]); return
            for i in range(len(a)):
                if used[i]:
                    continue
                if i and a[i] == a[i-1] and not used[i-1]:
                    continue
                used[i] = True; path.append(a[i])
                dfs()
                path.pop(); used[i] = False
        dfs()
        return res

class Solution {
public:
    void nextPermutation(vector<int>& a) {
        int n = a.size(), i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i >= 0) {
            int j = n - 1;
            while (a[j] <= a[i]) j--;
            swap(a[i], a[j]);
        }
        reverse(a.begin() + i + 1, a.end());
    }
};

class Solution:
    def nextPermutation(self, a: list[int]) -> None:
        n = len(a)
        i = n - 2
        while i >= 0 and a[i] >= a[i + 1]:
            i -= 1
        if i >= 0:
            j = n - 1
            while a[j] <= a[i]:
                j -= 1
            a[i], a[j] = a[j], a[i]
        a[i + 1:] = reversed(a[i + 1:])

class Solution {
    int n, count = 0; vector<bool> used;
    void dfs(int pos) {
        if (pos > n) { count++; return; }
        for (int v = 1; v <= n; v++)
            if (!used[v] && (v % pos == 0 || pos % v == 0)) {
                used[v] = true; dfs(pos + 1); used[v] = false;
            }
    }
public:
    int countArrangement(int N) { n = N; used.assign(n + 1, false); dfs(1); return count; }
};

class Solution:
    def countArrangement(self, n: int) -> int:
        used = [False] * (n + 1)
        self.count = 0
        def dfs(pos):
            if pos > n:
                self.count += 1
                return
            for v in range(1, n + 1):
                if not used[v] and (v % pos == 0 or pos % v == 0):
                    used[v] = True
                    dfs(pos + 1)
                    used[v] = False
        dfs(1)
        return self.count

class Solution {
    int dfs(vector<int>& cnt) {
        int total = 0;
        for (int i = 0; i < 26; i++)
            if (cnt[i] > 0) {
                total++; cnt[i]--;
                total += dfs(cnt);
                cnt[i]++;
            }
        return total;
    }
public:
    int numTilePossibilities(string tiles) {
        vector<int> cnt(26, 0);
        for (char c : tiles) cnt[c - 'A']++;
        return dfs(cnt);
    }
};

from collections import Counter
class Solution:
    def numTilePossibilities(self, tiles: str) -> int:
        cnt = Counter(tiles)
        def dfs():
            total = 0
            for ch in list(cnt):
                if cnt[ch] > 0:
                    total += 1
                    cnt[ch] -= 1
                    total += dfs()
                    cnt[ch] += 1
            return total
        return dfs()
